AuctioneerLocalizations.ruRU = {

		-- Section: Help
		["AAMU_Help_VendorOptions"]	= "Взаимодействие с торговцами";
		["AAMU_Help_VendorOptionsAnswer"]	= "Модуль позволяет автоматически продавать торговцам вещи, купленные через модуль поиска специально для перепродажи. Также с его помощью вы можете автоматически продавать вещи низкого качества (\"серые\") или вещи из составленного вами списка. Если любая из этих возможностей включена, то при общении с продавцом появится список вещей для автоматической продажи.";
		["AAMU_Help_WhatAutoMagic"]	= "Что такое AutoMagic?";
		["AAMU_Help_WhatAutoMagicAnswer"]	= "Задача AutoMagic - автоматизация однообразных действий с покупкой и продажей предметов, не противоречащая ограничениям Blizzard. Аддон находится в разработке и постоянно совершенствуется.";
		["AAMU_Help_WhatMailGUI"]	= "Что такое специальный почтовый интерфейс?";
		["AAMU_Help_WhatMailGUIAnswer"]	= "При входе в почтовый ящик интерфейс открывает окно, которое позволяет произвести автоподгрузку предметов в окно отправки, основываясь на причине их покупки на аукционе (через модуль SearchUI или ItemSuggest). Это удобно в случаях частых пересылок предметов, например купленных для профессии вашего другого персонажа.";
		["ADV_Help_CannotDeleteProfile"]	= "Невозможно удалить выбранный профиль";
		["ADV_Help_InvalidProfileName"]	= "Ошибка: укажите имя нового профиля";
		["ADV_Help_PostAuctionError"]	= "Этот предмет не может быть размещён из-за следующей ошибки: %s";
		["ADV_Help_UnresolvedAuctionsTolerance"]	= "Иногда в процессе сканирования Auctioneer не может определить кол-во аукционов, о чем говорит сообщение сканирование не закончено. Незаконченные сканирования позволяют Auctioneer отмечать их ему как законченные из-за небольшого процента ошибок. Это может использоваться на не стабильных серверах, обычно после выхода исправлений игры.";
		["ADV_Help_WhatAccuracy"]	= "Что является ошибкой Рыночной Оценки?";
		["ADV_Help_WhatAccuracyAnswer"]	= "Настройка отклонения от рыночной цены позволяет задать параметры отбрасывания определенной цены лота при подсчете рекомендованной стоимости покупки и продажи лотов. Цена не будет принята во внимание, если она отличается от заданных параметров средней цены по рынку. Уменьшение значения сделает оценку точнее, но увеличит загруженность ресурсов компьютера, что может вызвать притормаживание игры на слабых компьютерах.";
		["ADV_Help_WhatClickHooks"]	= "Что такое Маркеры?";
		["ADV_Help_WhatClickHooksAnswer"]	= "Маркеры позволяют вам выполнять удобный поиск лотов определенного предмета при помощи по комбинации клавиш Alt + правый клик для предмета в инвентаре (для ссылки в чате Alt + левый клик).";
		["ADV_Help_WhatExactMatch"]	= "Что такое точное совпадение?";
		["ADV_Help_WhatExactMatchAnswer"]	= "Названия некоторых предметов могут различаться не полностью, а лишь частично. Например, вторым словом в названии - \"Руническая ткань\" и \"Руническая нить\" или характеристиками одного и того же предмета. В этом случае, например поиск ткани по слову \"руническая\" выведет и нити. Включение настройки найти предметы в точном соответствии с заданными параметрами.";
		["ADV_Help_WhatIsImage"]	= "Что такое образ аукциона?";
		["ADV_Help_WhatIsImageAnswer"]	= "При сканировании Auctioneer создает список всех актуальных лотов - это и есть образ, \"срез\" торгов на данный момент. Если сканирование произошло только что, то вся информация (и, главное, цены) будет свежей, без обновлений она будет устаревать и может оказаться неверной.";
		["ADV_Help_WhatIsScanData"]	= "Что такое подсказка данных сканирования?";
		["ADV_Help_WhatIsScanDataAnswer"]	= "Это строчка во всплывающей подсказке к предмету, которая сообщает, сколько раз этот предмет был встречен в образах аукциона.";
		["ADV_Help_WhatPreferredChatFrame"]	= "Что такое \"выбор окна чата\"?";
		["ADV_Help_WhatPreferredChatFrameAnswer"]	= "Позволит выбрать окно чата, \"Основное\" или \"Бой\", куда будут выводится все сообщения Auctioneer'а.";
		["ADV_Help_WhatPreferredLanguage"]	= "Что такое предпочитаемый язык?";
		["ADV_Help_WhatPreferredLanguageAnswer"]	= "Они позволят выбрать один из поддерживаемых языков интерфейса Auctioneer'a. После смены требуется перезапуск аддона или введите команду /console reloadui.";
		["ADV_Help_WhatPriority"]	= "Что такое приоритет обработки данных?";
		["ADV_Help_WhatPriorityAnswer"]	= "Устанавливает скорость обработки данных в конце сканирования. Низкое значение увеличивает время обработки, но позволяет продолжить игру, без лагов. Высокий приоритет сокращает время записи образа, но увеличивает нагрузку на ресурсы компьютера\" до момента окончания записи. В последнем случае игра может тормозить.";
		["ADV_Help_WhyForceLoad"]	= "Почему вы хотите, чтобы данные сканирования загружались?";
		["ADV_Help_WhyForceLoadAnswer"]	= "Если Вы будете использовать данные образ во время игры, то некоторые предпочитают увеличение времени загрузки игры, чем лаги возникающие на несколько секунд при первом обращении к образу.";
		["ADV_Help_WhyShowSummation"]	= "Что такое отчет после сканирования?";
		["ADV_Help_WhyShowSummationAnswer"]	= "После сканирования отчет отображает количество новых, обновленных или оставшихся без изменений торгов.";
		["AHWC_Help_AuctionHouseScale"]	= "Масштаб окна аукциона";
		["AHWC_Help_AuctionHouseScaleAnswer"]	= "Это параметр регулирует общий размер всего окна аукциона. По умолчанию, используется значение 1.";
		["AHWC_Help_CompactUIFontScale"]	= "Размер шрифта CompactUI";
		["AHWC_Help_CompactUIFontScaleAnswer"]	= "Этот параметр регулирует размер текста, отображаемого в окне CompactUI. По умолчанию, используется значение 0.";
		["AHWC_Help_ProtectWindow"]	= "Что делает защита окна аукциона?";
		["AHWC_Help_ProtectWindowAnswer"]	= "Окно аукциона закрывается при открытии других окон (журнала заданий, окна гильдии и т.п.). Этот параметр позволяет открывать подобные окна в фоновом режиме, не прерывая процесс сканирования аукциона.";
		["AHWC_Help_RemberLastPosition"]	= "Запоминать последнюю позицию окна?";
		["AHWC_Help_RemberLastPositionAnswer"]	= "При включённом параметре, окно аукциона будет открываться в том месте экрана, где вы его оставили в прошлый раз.";
		["AHWC_Help_SearchUIScale"]	= "Масштаб SearchUI";
		["AHWC_Help_SearchUIScaleAnswer"]	= "Это параметр регулирует общий размер всего окна SearchUI. По умолчанию, используется значение 1.";
		["AHWC_Help_whatisthis"]	= "Что это за утилита?";
		["AHWC_Help_whatisthisAnswer"]	= "Эта утилита позволяет вам перемещать окно аукциона. Просто кликните и переместите куда вам угодно. Позволяет защитить окно аукциона от закрытия, при открытии др. окон Blizzard.";
		["APPR_Help_BatchFollowingWouldPosted"]	= "Следующие вещи будут размещены:";
		["APPR_Help_BatchPostHelp1"]	= "Механизм \"почтовая загрузка\" предоставляет возможность автоматических действий над всеми предметами в вашем инвентаре, для которых выбран этот механизм.";
		["APPR_Help_BatchPostHelp2"]	= "Вы должны держать зажатой одну из следующих комбинаций, когда нажимаете на кнопку:";
		["APPR_Help_BatchPostHelp3"]	= "- Alt = Авто-обновление всех отправленных вещей.";
		["APPR_Help_BatchPostHelp4"]	= "- Shift = Показать все аукционы которые были бы объявлены, не объявляя их.";
		["APPR_Help_BatchPostHelp5"]	= "- RightClick = Авто-объявление всех возможных автоматизированных аукционов.";
		["APPR_Help_BatchPostHelp6"]	= "- Alt+RightClick переключение пакетного выставления предмета на аукцион";
		["APPR_Help_BatchUnknownKeyCombo"]	= "Зажата неизвестная комбинация кнопок при нажатии кнопки отправки.";
		["APPR_Help_CannotPostAuctions"]	= "Невозможно объявить аукцион:";
		["APPR_Help_CouldNotPost"]	= "Не удалось выложить предмет";
		["APPR_Help_CouldNotQueue"]	= "Не возможно поставить в очередь предмет";
		["APPR_Help_Duration"]	= "Продолжительность: {{%d часов}}";
		["APPR_Help_HowBidPriceCalculated"]	= "Как рассчитывается стоимость ставки (bid price)?";
		["APPR_Help_HowBidPriceCalculatedAnswer"]	= "За исключением основных элементов цены, стартовая цена цена рассчитывается от первоначальной цены выкупа. Предложение вариантов расчета цены позволяют указать, как цена предложения снижается, и вариантов являются накопительными, поэтому, если вы установите оба уценки процентов, и вычесть стоимость депозит, то ставка стоимость будет рассчитываться как: (%s выкупа %s-%s снижение %s-%s залог %s).";
		["APPR_Help_HowMarkdownPctCalculated"]	= "Как вычисляется процент снижения цены?";
		["APPR_Help_HowMarkdownPctCalculatedAnswer"]	= "Результирующее значение вычисляется умножением рассчитанного значения на значение в процентах, которое указано в настройках. После этого, это значение вычитается из расчётной величины (вместе с фиксированной величиной вычета и/или величиной депозита, если она указана) для получения начальной цены ставки";
		["APPR_Help_NeedOnlyHavePosting"]	= "Нужно %d из %s, есть только %d, отправлено %d";
